// === Tab: mySketch ===
// FriedRiceWithoutMarcy_1.1

let N = 600 ; let M = 1 ; let K = 0.5 ; let KK = 0.5 ; let G = 0.1 ; let R = 6 ; let PR = 200 ; 
let H = 0.95 ; let PVmax = 3 ; let PRR = 240 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let VX[] = new Array(N) ; let VY[] = new Array(N) ;
let FX[] = new Array(N) ; let FY[] = new Array(N) ;
let T[] = new Array(N) ; let J[] = new Array(N) ; let dT[] = new Array(N) ;
let PX ; let PY ; let PVX ; let PVY ; let I ; let II ; let L ; let RW ; let RRW ; 
let S[] = new Array(4) ;

function setup(){
  createCanvas(900, 600) ; noSmooth() ; textSize(20) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(300,600) ; Y[I] = random(-700,-100) ;
  }//let PX = PR ; PY = PR ; RW = (PR+PRR)/2 ; RRW = (PRR-PR)/2 ;
}//setup()

function draw(){
  background(0) ;
  for ( II = 0 ; II < 250 ; II++ ){
    stroke(II,0,0) ; line(0,350+II,900,350+II) ;
  }//II
  stroke(0) ; fill(100) ; rect(PX-RW,PY,-250,40) ;
  stroke(140) ; noFill() ; strokeWeight(RRW*1.5) ;
  arc(PX,PY,RW*2,RW*2,0,PI) ; strokeWeight(2) ; 
  PVX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - PX ;
  PVY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - PY ;
  L = sqrt(pow(PVX,2)+pow(PVY,2)) ;
  if ( L > PVmax ){ PVX = PVX * PVmax/L ; PVY = PVY * PVmax/L ; }
  PX = PX + PVX ; PY = PY + PVY ; 
  if ( PX < RW ){ PX = RW ; }
  if ( PX > 900-RW ){ PX = 900-RW ; }
	if ( PY > 600-PRR ){ PY = 600-PRR ; }
  for ( I = 0 ; I < N ; I++ ){
    for ( II = I ; II < N ; II++ ){
      L = sqrt(pow(X[I]-X[II],2)+pow(Y[I]-Y[II],2)) ;
      if ( L < 2*R && L > 0 ){
       FX[I] = FX[I] - ((2*R-L)*K*(X[II]-X[I])/L) ; 
       FY[I] = FY[I] - ((2*R-L)*K*(Y[II]-Y[I])/L) ; 
       FX[II] = FX[II] + ((2*R-L)*K*(X[II]-X[I])/L) ; 
       FY[II] = FY[II] + ((2*R-L)*K*(Y[II]-Y[I])/L) ; 
       dT[I] = dT[I] + ((T[I]-T[II])/10) ; 
       dT[II] = dT[II] - ((T[I]-T[II])/10) ; 
      }
    }//II
    if ( Y[I] > PY ){
      L = sqrt(pow(X[I]-PX,2)+pow(Y[I]-PY,2)) ;
      if ( L > PR && L < RW ){
        FX[I] = FX[I] + ((L-PR)*KK*(PX-X[I])/L) ; 
        FY[I] = FY[I] + ((L-PR)*KK*(PY-Y[I])/L) ; 
      }
      if ( L > RW && L < PRR ){
        FX[I] = FX[I] + ((L-PRR)*KK*(PX-X[I])/L) ; 
        FY[I] = FY[I] + ((L-PRR)*KK*(PY-Y[I])/L) ; 
      }
    }else{
      L = sqrt(pow(X[I]-(PX+RW),2)+pow(Y[I]-PY,2)) ;
      if ( L < RRW ){
        FX[I] = FX[I] - ((RRW-L)*KK*(PX+RW-X[I])/L) ; 
        FY[I] = FY[I] - ((RRW-L)*KK*(PY-Y[I])/L) ; 
      }
      L = sqrt(pow(X[I]-(PX-RW),2)+pow(Y[I]-PY,2)) ;
      if ( L < RRW ){
        FX[I] = FX[I] - ((RRW-L)*KK*(PX-RW-X[I])/L) ; 
        FY[I] = FY[I] - ((RRW-L)*KK*(PY-Y[I])/L) ; 
      }
    }
    FY[I] = FY[I] + (M*G) ;
    if ( Y[I] > 400 ){ dT[I] = (Y[I]-400)/100 ; }
                 else{ dT[I] = (Y[I]-400)/1000 ; }
  }//I 
  for ( I = 0 ; I < N ; I++ ){
    T[I] = T[I] + dT[I] ; 
    if ( T[I] < 0 ){ T[I] = 0 ; }
    if ( J[I] < 2 && T[I] <  150 ){ J[I] = 0 ; }
    if ( J[I] < 2 && T[I] >= 150 ){ J[I] = 1 ; }
    if ( J[I] != 2 && T[I] > 500 ){ J[I] = 3 ; }
    if ( Y[I] > 600+R ){ J[I] = 2 ; }
    VX[I] = ( VX[I] + (FX[I]/M) ) * H ;
    VY[I] = ( VY[I] + (FY[I]/M) ) * H ;
    X[I] = X[I] + VX[I] ; Y[I] = Y[I] + VY[I] ; 
    FX[I] = 0 ; FY[I] = 0 ;
    if ( J[I] == 3 ){ fill(0) ; stroke(255,255-T[I],255-T[I]) ; }
                else{ stroke(0) ; fill(255,255-T[I],255-T[I]) ; }
    ellipse(X[I],Y[I],2*R,2*R) ;
    S[J[I]] = S[J[I]] + 1 ;
  }//I
  fill(255) ; 
  text("Cold Rice :"+int(float(S[0])/float(N)*100)+"%",0,20) ;
  text("Hot Rice :"+int(float(S[1])/float(N)*100)+"%",0,40) ;
  text("Burnt Rice :"+int(float(S[3])/float(N)*100)+"%",0,60) ;
  text("Lost Rice :"+int(float(S[2])/float(N)*100)+"%",0,80) ;
  for ( II = 0 ; II < 4 ; II++ ){ S[II] = 0 ; }
}//draw()

